<script lang="ts">
 let {home,role,onchanged}=$props<{home:any,role:string,onchanged:()=>Promise<void>}>();
 let title=$state('');let entityId=$state('');let files:FileList|undefined=$state();let saving=$state(false);let message=$state('');let pending:{id:string,homeId:string,title:string,entityId:string,file:File}|null=$state(null);
 async function save(){
  if(!pending){const file=files?.[0];if(!file){message='Choose a source file.';return;}pending={id:crypto.randomUUID(),homeId:home.id,title,entityId,file};}
  saving=true;message='';const form=new FormData();form.set('id',pending.id);form.set('homeId',pending.homeId);form.set('title',pending.title);if(pending.entityId)form.set('entityId',pending.entityId);form.set('file',pending.file);
  try{const r=await fetch('/api/home/evidence',{method:'POST',body:form});const data=await r.json();if(!r.ok){if(r.status===400)pending=null;throw new Error(data.message??'Confirmation unavailable; retry the same file.');}
   if(data.status==='pending-readback'){message='Confirmation pending. Keep this file and retry this same entry.';}else{pending=null;message='Original saved privately with your account and checksum.';await onchanged();}
  }catch(e){message=e instanceof Error?e.message:String(e);}finally{saving=false;}
 }
</script>
{#if role!=='viewer'}<section><h2>Add a source</h2><p>Keep a label photo, invoice, plan or note with your home records. Original files stay private in your Fulcra account. Adding evidence does not automatically change a fact or mark work complete.</p><form onsubmit={e=>{e.preventDefault();save();}}><fieldset disabled={saving||!!pending}><label>Source title <input bind:value={title} maxlength="500" required placeholder="Boiler label photo or annual service invoice" /></label><label>Related equipment <select bind:value={entityId}><option value="">Whole home</option>{#each home.equipment??[] as item}<option value={item.id}>{item.name}</option>{/each}</select></label><label>Source file <input type="file" accept="image/png,image/jpeg,image/webp,application/pdf,text/plain" bind:files required /></label><p>PNG, JPEG, WebP, PDF or UTF-8 text; up to 3 MiB. Keep larger scans in Fulcra and give your agent the file reference.</p></fieldset><button disabled={saving}>{saving?'Saving original…':pending?'Retry same source':'Save source privately'}</button></form><p role="status">{message}</p><p>Household contributors must explicitly share this home’s Sources folder with intended recipients through Fulcra. Uploading here does not grant anyone new access.</p></section>{/if}
<style>section{margin:30px 0}h2{font-size:25px}p{line-height:1.6}form{max-width:620px}label{display:block;margin:15px 0}input,select{display:block;width:100%;padding:12px;background:white;color:#202c2c;border:1px solid #becfc5;border-radius:8px;margin:8px 0}button{background:white;border:1px solid #cadbd1;border-radius:8px;padding:10px 16px;color:#254a3c;cursor:pointer}fieldset{border:0;padding:0}</style>
